#include "task.h"

/**
 * @brief Parses a CCSDS primary header from a buffer.
 *
 * @param buf Pointer to the input buffer containing the CCSDS header. Must not be NULL.
 * @param len Length of the input buffer in bytes. Must be at least 6.
 * @param hdr Pointer to the output header structure. Must not be NULL.
 * @return 0 on success, -1 if buf/hdr NULL or len < 6, -2 if version != 0.
 */
int ccsds_parse_primary(const uint8_t *buf, size_t len, ccsds_primary_header_t *hdr)
{
    if (buf == NULL || hdr == NULL || len < 6u) {
        return -1;
    }
    uint16_t w0 = (uint16_t)(((uint16_t)buf[0] << 8) | buf[1]);
    uint16_t w1 = (uint16_t)(((uint16_t)buf[2] << 8) | buf[3]);
    hdr->version = (uint8_t)(w0 >> 13);
    hdr->type = (uint8_t)((w0 >> 12) & 1u);
    hdr->sec_hdr = (uint8_t)((w0 >> 11) & 1u);
    hdr->apid = (uint16_t)(w0 & 0x7FFu);
    hdr->seq_flags = (uint8_t)(w1 >> 14);
    hdr->seq_count = (uint16_t)(w1 & 0x3FFFu);
    hdr->data_length = (uint16_t)(((uint16_t)buf[4] << 8) | buf[5]);
    return hdr->version == 0u ? 0 : -2;
}

/**
 * @brief Calculates the total length of a CCSDS packet.
 *
 * @param hdr Pointer to the CCSDS primary header structure. Must not be NULL.
 * @return Total packet length in bytes, including header, data, and checksum.
 */
size_t ccsds_packet_length(const ccsds_primary_header_t *hdr) { return 6u + (size_t)hdr->data_length + 1u; }

#include "task.h"

/**
 * @brief Clamps a value between a lower and upper bound.
 * @param v The value to clamp.
 * @param lo The lower bound (inclusive).
 * @param hi The upper bound (inclusive).
 * @return The clamped value.
 */
static int32_t clamp(int32_t v, int32_t lo, int32_t hi)
{
    if (v < lo) {
        return lo;
    }
    if (v > hi) {
        return hi;
    }
    return v;
}

/**
 * @brief Initializes a PID controller instance.
 * @param p Pointer to the PID controller instance to initialize.
 * @param kp_q8 Proportional gain in Q8 format (fixed-point with 8 fractional bits).
 * @param ki_q8 Integral gain in Q8 format.
 * @param kd_q8 Derivative gain in Q8 format.
 * @param out_min Minimum output value.
 * @param out_max Maximum output value.
 * @pre p must not be NULL.
 * @pre out_min must be less than or equal to out_max.
 */
void pid_init(pid_t_ *p, int32_t kp_q8, int32_t ki_q8, int32_t kd_q8, int32_t out_min, int32_t out_max)
{
    p->kp_q8 = kp_q8;
    p->ki_q8 = ki_q8;
    p->kd_q8 = kd_q8;
    p->integral = 0;
    p->integral_limit = 100000;
    p->prev_error = 0;
    p->out_min = out_min;
    p->out_max = out_max;
}

/**
 * @brief Performs a single PID control step.
 * @param p Pointer to the PID controller instance.
 * @param setpoint The desired target value.
 * @param measurement The current measured value.
 * @return The calculated control output, clamped between out_min and out_max.
 * @pre p must not be NULL.
 * @pre out_min must be less than or equal to out_max.
 */
int32_t pid_step(pid_t_ *p, int32_t setpoint, int32_t measurement)
{
    int32_t error = setpoint - measurement;
    int32_t derivative = error - p->prev_error;
    p->integral = clamp(p->integral + error, -p->integral_limit, p->integral_limit);
    p->prev_error = error;
    int32_t out = (p->kp_q8 * error + p->ki_q8 * p->integral + p->kd_q8 * derivative) / 256;
    return clamp(out, p->out_min, p->out_max);
}

#include "task.h"

/**
 * @brief Initializes a ring buffer to empty state.
 * @param rb Pointer to the ring buffer to initialize. Must not be NULL.
 */
void rb_init(ring_buffer_t *rb)
{
    rb->head = 0u;
    rb->tail = 0u;
    rb->count = 0u;
}

/**
 * @brief Pushes a byte onto the ring buffer.
 * @param rb Pointer to the ring buffer. Must not be NULL.
 * @param byte The byte value to store.
 * @return true if the byte was stored, false if the buffer was full.
 */
bool rb_push(ring_buffer_t *rb, uint8_t byte)
{
    if (rb->count >= RB_CAPACITY) {
        return false;
    }
    rb->data[rb->head] = byte;
    rb->head = (rb->head + 1u) % RB_CAPACITY;
    rb->count++;
    return true;
}

/**
 * @brief Pops a byte from the ring buffer.
 * @param rb Pointer to the ring buffer. Must not be NULL.
 * @param out Pointer to store the popped byte. Must not be NULL.
 * @return true if a byte was successfully popped, false if the buffer was empty.
 */
bool rb_pop(ring_buffer_t *rb, uint8_t *out)
{
    if (rb->count == 0u) {
        return false;
    }
    *out = rb->data[rb->tail];
    rb->tail = (rb->tail + 1u) % RB_CAPACITY;
    rb->count--;
    return true;
}

/**
 * @brief Gets the current number of bytes stored in the ring buffer.
 * @param rb Pointer to the ring buffer. Must not be NULL.
 * @return Number of bytes currently stored in the buffer (0 to RB_CAPACITY).
 */
size_t rb_count(const ring_buffer_t *rb) { return rb->count; }

/**
 * @brief Pushes multiple bytes onto the ring buffer.
 * @param rb Pointer to the ring buffer. Must not be NULL.
 * @param src Pointer to the source data. Must not be NULL.
 * @param n Number of bytes to store. Must be non-negative.
 * @return Number of bytes actually stored (0 to n, or up to buffer capacity).
 */
size_t rb_push_many(ring_buffer_t *rb, const uint8_t *src, size_t n)
{
    size_t stored = 0u;
    while (stored < n && rb_push(rb, src[stored])) {
        stored++;
    }
    return stored;
}

