/**
 * @brief Clamps a 32-bit integer to the 16-bit signed integer range [INT16_MIN, INT16_MAX].
 * @param v The 32-bit integer value to clamp.
 * @return The clamped value in the range [INT16_MIN, INT16_MAX].
 */
static int16_t clamp16(int32_t v)
{
    if (v > INT16_MAX) {
        return INT16_MAX;
    }
    if (v < INT16_MIN) {
        return INT16_MIN;
    }
    return (int16_t)v;
}

/**
 * @brief Performs saturating addition of two 16-bit signed integers.
 * @param a The first 16-bit signed integer operand.
 * @param b The second 16-bit signed integer operand.
 * @return The sum of a and b, clamped to the range [INT16_MIN, INT16_MAX].
 *         If the result would overflow, returns INT16_MAX.
 *         If the result would underflow, returns INT16_MIN.
 */
int16_t sat_add16(int16_t a, int16_t b) { return clamp16((int32_t)a + (int32_t)b); }

/**
 * @brief Performs saturating subtraction of two 16-bit signed integers.
 * @param a The 16-bit signed integer minuend.
 * @param b The 16-bit signed integer subtrahend.
 * @return The difference of a minus b, clamped to the range [INT16_MIN, INT16_MAX].
 *         If the result would overflow, returns INT16_MAX.
 *         If the result would underflow, returns INT16_MIN.
 */
int16_t sat_sub16(int16_t a, int16_t b) { return clamp16((int32_t)a - (int32_t)b); }

/**
 * @brief Computes the absolute value of a 16-bit signed integer with saturation.
 * @param a The 16-bit signed integer operand.
 * @return The absolute value of a, clamped to the range [0, INT16_MAX].
 *         Special case: sat_abs16(INT16_MIN) returns INT16_MAX to avoid overflow.
 */
int16_t sat_abs16(int16_t a) { return clamp16(a < 0 ? -(int32_t)a : (int32_t)a); }

#include "task.h"

int ccsds_parse_primary(const uint8_t *buf, size_t len, ccsds_primary_header_t *hdr)
{
    if (buf == NULL || hdr == NULL || len < 6) {
        return -1;
    }

    uint8_t version = (buf[0] >> 5) & 0x07;
    if (version != 0) {
        return -2;
    }

    hdr->version = version;
    hdr->type = (buf[0] >> 4) & 0x01;
    hdr->sec_hdr = (buf[0] >> 3) & 0x01;
    hdr->apid = ((buf[0] & 0x07) << 8) | buf[1];
    hdr->seq_flags = (buf[2] >> 6) & 0x03;
    hdr->seq_count = ((buf[2] & 0x3F) << 8) | buf[3];
    hdr->data_length = ((buf[4] & 0xFF) << 8) | buf[5];

    return 0;
}

size_t ccsds_packet_length(const ccsds_primary_header_t *hdr)
{
    return 6 + hdr->data_length + 1;
}

int ccsds_build_primary(const ccsds_primary_header_t *hdr, uint8_t out[6])
{
    if (hdr == NULL || out == NULL) {
        return -1;
    }

    if (hdr->version > 7 || hdr->type > 1 || hdr->sec_hdr > 1 ||
        hdr->apid > 2047 || hdr->seq_flags > 3 || hdr->seq_count > 16383) {
        return -1;
    }

    out[0] = (hdr->version << 5) | (hdr->type << 4) | (hdr->sec_hdr << 3) | ((hdr->apid >> 8) & 0x07);
    out[1] = hdr->apid & 0xFF;
    out[2] = (hdr->seq_flags << 6) | ((hdr->seq_count >> 8) & 0x3F);
    out[3] = hdr->seq_count & 0xFF;
    out[4] = (hdr->data_length >> 8) & 0xFF;
    out[5] = hdr->data_length & 0xFF;

    return 0;
}

