size_t cobs_encode(const uint8_t *src, size_t len, uint8_t *dst)
{
    if (dst == NULL || src == NULL) {
        return 0;
    }

    size_t read_index = 0;
    size_t write_index = 1;
    size_t code_index = 0;
    uint8_t code = 1;

    while (read_index < len) {
        if (src[read_index] == 0) {
            dst[code_index] = code;
            code_index = write_index++;
            code = 1;
        } else {
            dst[write_index++] = src[read_index];
            code++;
        }
        read_index++;
    }

    dst[code_index] = code;
    return write_index;
}

size_t cobs_decode(const uint8_t *src, size_t len, uint8_t *dst)
{
    if (src == NULL || dst == NULL || len == 0) {
        return 0;
    }

    size_t read_index = 0;
    size_t write_index = 0;
    uint8_t code = 0;
    uint8_t i = 0;

    while (read_index < len) {
        code = src[read_index];
        if (code == 0) {
            return 0;
        }
        if (read_index + code > len) {
            return 0;
        }
        for (i = 1; i < code; i++) {
            if (read_index + i >= len) {
                return 0;
            }
            if (src[read_index + i] == 0) {
                return 0;
            }
            dst[write_index++] = src[read_index + i];
        }
        read_index += code;
    }

    return write_index;
}

