size_t conv_encode(const uint8_t *in, size_t nbits, uint8_t *out) {
    uint8_t p1 = 0;  // previous input bit
    uint8_t p2 = 0;  // bit before previous input bit
    uint8_t out_byte = 0;
    size_t out_bit_count = 0;

    for (size_t i = 0; i < nbits; i++) {
        // Extract current input bit (MSB first)
        uint8_t u = (in[i / 8] >> (7 - (i % 8))) & 1;

        // Calculate output bits using generator polynomials
        uint8_t out0 = u ^ p1 ^ p2;  // generator 7 (111b)
        uint8_t out1 = u ^ p2;       // generator 5 (101b)

        // Append output bits to output byte
        out_byte |= (out0 << (7 - out_bit_count));
        out_bit_count++;

        if (out_bit_count == 8) {
            out[i / 4] = out_byte;
            out_byte = 0;
            out_bit_count = 0;
        }

        out_byte |= (out1 << (7 - out_bit_count));
        out_bit_count++;

        if (out_bit_count == 8) {
            out[i / 4 + 1] = out_byte;
            out_byte = 0;
            out_bit_count = 0;
        }

        // Shift registers
        p2 = p1;
        p1 = u;
    }

    // Handle remaining bits in the last byte
    if (out_bit_count > 0) {
        // Pad with zeros to make a complete byte
        out_byte <<= (8 - out_bit_count);
        out[(nbits * 2 + 7) / 8 - 1] = out_byte;
    }

    return nbits * 2;
}

