uint16_t crc16_ccitt_false(const uint8_t *data, size_t len) {
    uint16_t crc = 0xFFFF;

    for (size_t i = 0; i < len; i++) {
        uint8_t table_index = (crc >> 8) ^ data[i];
        crc = (crc << 8) ^ crc_table[table_index];
    }

    return crc;
}

uint16_t crc16_ccitt_update(uint16_t crc, const uint8_t *data, size_t len) {
    for (size_t i = 0; i < len; i++) {
        uint8_t table_index = (crc >> 8) ^ data[i];
        crc = (crc << 8) ^ crc_table[table_index];
    }

    return crc;
}

#include "task.h"

static uint32_t crc_table[256];

static void crc32_init(void) {
    static int initialized = 0;
    if (initialized) return;

    const uint32_t polynomial = 0xEDB88320;
    for (int i = 0; i < 256; i++) {
        uint32_t crc = i;
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ polynomial;
            } else {
                crc >>= 1;
            }
        }
        crc_table[i] = crc;
    }
    initialized = 1;
}

uint32_t crc32_ieee(const uint8_t *data, size_t len) {
    crc32_init();

    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++) {
        uint8_t table_index = (crc ^ data[i]) & 0xFF;
        crc = (crc >> 8) ^ crc_table[table_index];
    }
    return crc ^ 0xFFFFFFFF;
}

uint32_t crc32_ieee_update(uint32_t crc, const uint8_t *data, size_t len) {
    crc32_init();

    crc ^= 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++) {
        uint8_t table_index = (crc ^ data[i]) & 0xFF;
        crc = (crc >> 8) ^ crc_table[table_index];
    }
    return crc ^ 0xFFFFFFFF;
}

#include "task.h"

void debounce_init(debounce_t *d, bool initial)
{
    d->state = initial;
    d->count = 0u;
}

bool debounce_update(debounce_t *d, bool raw)
{
    if (raw == d->state) {
        d->count = 0u;
    } else {
        d->count++;
        if (d->count >= DEBOUNCE_SAMPLES) {
            d->state = raw;
            d->count = 0u;
        }
    }
    return d->state;
}

