uint16_t read_be16(const uint8_t *p)
{
    return (uint16_t)p[0] << 8 |
           (uint16_t)p[1];
}

uint32_t read_be32(const uint8_t *p)
{
    return (uint32_t)p[0] << 24 |
           (uint32_t)p[1] << 16 |
           (uint32_t)p[2] << 8  |
           (uint32_t)p[3];
}

uint16_t read_le16(const uint8_t *p)
{
    return (uint16_t)p[0] |
           (uint16_t)p[1] << 8;
}

uint32_t read_le32(const uint8_t *p)
{
    return (uint32_t)p[0] |
           (uint32_t)p[1] << 8  |
           (uint32_t)p[2] << 16 |
           (uint32_t)p[3] << 24;
}

void write_be16(uint8_t *p, uint16_t v)
{
    p[0] = (uint8_t)(v >> 8);
    p[1] = (uint8_t)v;
}

void write_be32(uint8_t *p, uint32_t v)
{
    p[0] = (uint8_t)(v >> 24);
    p[1] = (uint8_t)(v >> 16);
    p[2] = (uint8_t)(v >> 8);
    p[3] = (uint8_t)v;
}

void write_le32(uint8_t *p, uint32_t v)
{
    p[0] = (uint8_t)v;
    p[1] = (uint8_t)(v >> 8);
    p[2] = (uint8_t)(v >> 16);
    p[3] = (uint8_t)(v >> 24);
}

