uint8_t hamming74_encode(uint8_t nibble) {
    uint8_t p1, p2, p3;
    uint8_t d1, d2, d3, d4;

    d1 = (nibble >> 3) & 1;
    d2 = (nibble >> 2) & 1;
    d3 = (nibble >> 1) & 1;
    d4 = nibble & 1;

    p1 = (d1 ^ d2 ^ d4) & 1;
    p2 = (d1 ^ d3 ^ d4) & 1;
    p3 = (d2 ^ d3 ^ d4) & 1;

    return (p1 << 6) | (p2 << 5) | (d1 << 4) | (p3 << 3) | (d2 << 2) | (d3 << 1) | d4;
}

int hamming74_decode(uint8_t codeword, uint8_t *nibble) {
    uint8_t p1, p2, p3;
    uint8_t d1, d2, d3, d4;
    uint8_t s1, s2, s3;
    uint8_t syndrome;

    p1 = (codeword >> 6) & 1;
    p2 = (codeword >> 5) & 1;
    d1 = (codeword >> 4) & 1;
    p3 = (codeword >> 3) & 1;
    d2 = (codeword >> 2) & 1;
    d3 = (codeword >> 1) & 1;
    d4 = codeword & 1;

    s1 = (p1 ^ d1 ^ d2 ^ d4) & 1;
    s2 = (p2 ^ d1 ^ d3 ^ d4) & 1;
    s3 = (p3 ^ d2 ^ d3 ^ d4) & 1;

    syndrome = (s3 << 2) | (s2 << 1) | s1;

    if (syndrome == 0) {
        *nibble = (d1 << 3) | (d2 << 2) | (d3 << 1) | d4;
        return 0;
    }

    if (syndrome == 1) {
        d1 ^= 1;
    } else if (syndrome == 2) {
        d2 ^= 1;
    } else if (syndrome == 3) {
        d3 ^= 1;
    } else if (syndrome == 4) {
        d4 ^= 1;
    } else if (syndrome == 5) {
        p1 ^= 1;
    } else if (syndrome == 6) {
        p2 ^= 1;
    } else if (syndrome == 7) {
        p3 ^= 1;
    }

    *nibble = (d1 << 3) | (d2 << 2) | (d3 << 1) | d4;
    return 1;
}

