void scrambler_init(scrambler_t *s, uint8_t seed) {
    s->state = (seed & 0x7F) ? (seed & 0x7F) : 0x7F;
}

void scrambler_apply(scrambler_t *s, const uint8_t *in, uint8_t *out, size_t len) {
    for (size_t i = 0; i < len; i++) {
        uint8_t byte = in[i];
        uint8_t result = 0;

        for (int bit = 0; bit < 8; bit++) {
            uint8_t b = (byte >> bit) & 1;
            uint8_t fb = (s->state >> 6) ^ ((s->state >> 3) & 1);
            result |= ((b ^ fb) << bit);

            s->state = ((s->state << 1) | fb) & 0x7F;
        }

        out[i] = result;
    }
}

#include "task.h"

q15_t q15_add_sat(q15_t a, q15_t b) {
    // Check for overflow before addition
    if (a > 0 && b > 0 && a > 32767 - b) {
        return 32767;  // Overflow: return maximum positive value
    }
    if (a < 0 && b < 0 && a < -32768 - b) {
        return -32768; // Underflow: return minimum negative value
    }
    return a + b;
}

q15_t q15_mul(q15_t a, q15_t b) {
    // Use int32_t for intermediate calculation to avoid overflow
    int32_t product = (int32_t)a * (int32_t)b;

    // Round half up: add 2^14 (16384) before right shift by 15
    // This is equivalent to adding 2^14 and then dividing by 2^15
    int32_t rounded = product + 16384;

    // Right shift by 15 to get the final result
    int32_t result = rounded >> 15;

    // Clamp to Q15 range [-32768, 32767]
    if (result > 32767) {
        return 32767;
    }
    if (result < -32768) {
        return -32768;
    }
    return (q15_t)result;
}

