void rb_init(ring_buffer_t *rb)
{
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

bool rb_push(ring_buffer_t *rb, uint8_t byte)
{
    if (rb_is_full(rb)) {
        return false;
    }

    rb->data[rb->head] = byte;
    rb->head = (rb->head + 1) % RB_CAPACITY;
    rb->count++;
    return true;
}

bool rb_pop(ring_buffer_t *rb, uint8_t *out)
{
    if (rb->count == 0) {
        return false;
    }

    *out = rb->data[rb->tail];
    rb->tail = (rb->tail + 1) % RB_CAPACITY;
    rb->count--;
    return true;
}

size_t rb_count(const ring_buffer_t *rb)
{
    return rb->count;
}

bool rb_is_full(const ring_buffer_t *rb)
{
    return rb->count == RB_CAPACITY;
}

size_t rb_push_many(ring_buffer_t *rb, const uint8_t *src, size_t n)
{
    size_t i;
    for (i = 0; i < n && !rb_is_full(rb); i++) {
        rb->data[rb->head] = src[i];
        rb->head = (rb->head + 1) % RB_CAPACITY;
        rb->count++;
    }
    return i;
}

