#define MODE_MIN 0
#define MODE_MAX 3
#define GAIN_MIN 0
#define GAIN_MAX 63
#define CHANNEL_MIN 1
#define CHANNEL_MAX 15
#define RESET_ARG 0xA5

static int set_mode(payload_state_t *s, uint8_t arg)
{
    if (arg < MODE_MIN || arg > MODE_MAX) {
        s->err_count++;
        return -2;
    }
    s->mode = arg;
    s->cmd_count++;
    return 0;
}

static int set_gain(payload_state_t *s, uint8_t arg)
{
    if (s->mode == MODE_MIN) {
        s->err_count++;
        return -3;
    }
    if (arg < GAIN_MIN || arg > GAIN_MAX) {
        s->err_count++;
        return -2;
    }
    s->gain = arg;
    s->cmd_count++;
    return 0;
}

static int set_channel(payload_state_t *s, uint8_t arg)
{
    if (s->mode == MODE_MIN) {
        s->err_count++;
        return -3;
    }
    if (arg < CHANNEL_MIN || arg > CHANNEL_MAX) {
        s->err_count++;
        return -2;
    }
    s->channel = arg;
    s->cmd_count++;
    return 0;
}

static int reset(payload_state_t *s, uint8_t arg)
{
    if (arg != RESET_ARG) {
        s->err_count++;
        return -2;
    }
    s->mode = MODE_MIN;
    s->gain = 10;
    s->channel = 1;
    s->cmd_count++;
    return 0;
}

static int ping(payload_state_t *s, uint8_t arg)
{
    (void)arg;
    s->cmd_count++;
    return 0;
}

void payload_init(payload_state_t *s)
{
    s->mode = MODE_MIN;
    s->gain = 10;
    s->channel = 1;
    s->cmd_count = 0;
    s->err_count = 0;
}

int payload_dispatch(payload_state_t *s, uint8_t opcode, uint8_t arg)
{
    switch (opcode) {
    case 1: return set_mode(s, arg);
    case 2: return set_gain(s, arg);
    case 3: return set_channel(s, arg);
    case 4: return reset(s, arg);
    case 5: return ping(s, arg);
    default:
        s->err_count++;
        return -1;
    }
}

