#define FREQUENCY_MIN_KHZ 400000
#define FREQUENCY_MAX_KHZ 470000
#define FREQUENCY_STEP_KHZ 25
#define BANDWIDTH_VALID_VALUES_COUNT 3
#define SPREADING_FACTOR_MIN 7
#define SPREADING_FACTOR_MAX 12
#define TX_POWER_MIN_DBM -4
#define TX_POWER_MAX_DBM 20
#define DUTY_CYCLE_MIN_PCT 1
#define DUTY_CYCLE_MAX_PCT 100
#define BANDWIDTH_500_KHZ 500
#define SPREADING_FACTOR_MAX_500_KHZ 10
#define TX_POWER_MAX_14_DBM 14
#define DUTY_CYCLE_MAX_10_PCT 10

static const uint16_t bandwidth_valid_values[BANDWIDTH_VALID_VALUES_COUNT] = {125, 250, 500};

static int is_valid_frequency(const radio_cfg_t *c)
{
    if (c->frequency_khz < FREQUENCY_MIN_KHZ || c->frequency_khz > FREQUENCY_MAX_KHZ) {
        return 0;
    }
    if (c->frequency_khz % FREQUENCY_STEP_KHZ != 0) {
        return 0;
    }
    return 1;
}

static int is_valid_bandwidth(const radio_cfg_t *c)
{
    for (int i = 0; i < BANDWIDTH_VALID_VALUES_COUNT; i++) {
        if (c->bandwidth_khz == bandwidth_valid_values[i]) {
            return 1;
        }
    }
    return 0;
}

static int is_valid_spreading_factor(const radio_cfg_t *c)
{
    return (c->spreading_factor >= SPREADING_FACTOR_MIN && 
            c->spreading_factor <= SPREADING_FACTOR_MAX);
}

static int is_valid_tx_power(const radio_cfg_t *c)
{
    return (c->tx_power_dbm >= TX_POWER_MIN_DBM && 
            c->tx_power_dbm <= TX_POWER_MAX_DBM);
}

static int is_valid_bandwidth_spreading_factor_combination(const radio_cfg_t *c)
{
    if (c->bandwidth_khz == BANDWIDTH_500_KHZ && c->spreading_factor > SPREADING_FACTOR_MAX_500_KHZ) {
        return 0;
    }
    return 1;
}

static int is_valid_tx_power_duty_cycle_combination(const radio_cfg_t *c)
{
    if (c->tx_power_dbm > TX_POWER_MAX_14_DBM && c->duty_cycle_pct > DUTY_CYCLE_MAX_10_PCT) {
        return 0;
    }
    return 1;
}

static int is_valid_duty_cycle(const radio_cfg_t *c)
{
    return (c->duty_cycle_pct >= DUTY_CYCLE_MIN_PCT && 
            c->duty_cycle_pct <= DUTY_CYCLE_MAX_PCT);
}

int radio_cfg_validate(const radio_cfg_t *c)
{
    if (!is_valid_frequency(c)) {
        return 1;
    }
    if (!is_valid_bandwidth(c)) {
        return 3;
    }
    if (!is_valid_spreading_factor(c)) {
        return 4;
    }
    if (!is_valid_tx_power(c)) {
        return 5;
    }
    if (!is_valid_bandwidth_spreading_factor_combination(c)) {
        return 6;
    }
    if (!is_valid_tx_power_duty_cycle_combination(c)) {
        return 7;
    }
    if (!is_valid_duty_cycle(c)) {
        return 8;
    }
    return 0;
}

#include "task.h"

#define SYNC_BYTE1 0xEB
#define SYNC_BYTE2 0x90
#define MIN_FRAME_SIZE 5
#define MAX_PAYLOAD_SIZE 32
#define MIN_TYPE 0x10
#define MAX_TYPE 0x1F

static int validate_input(const uint8_t *buf, size_t len, uint8_t *type, uint8_t *out)
{
    if (buf == NULL || type == NULL || out == NULL) {
        return -1;
    }
    if (len < MIN_FRAME_SIZE) {
        return -1;
    }
    if (buf[0] != SYNC_BYTE1 || buf[1] != SYNC_BYTE2) {
        return -2;
    }
    return 0;
}

static int validate_length(const uint8_t *buf, size_t len)
{
    uint8_t payload_len = buf[2];
    if (payload_len == 0 || payload_len > MAX_PAYLOAD_SIZE) {
        return -3;
    }
    if (payload_len + MIN_FRAME_SIZE != len) {
        return -3;
    }
    return 0;
}

static int validate_type(const uint8_t *buf)
{
    uint8_t type = buf[3];
    if (type < MIN_TYPE || type > MAX_TYPE) {
        return -4;
    }
    return 0;
}

static int validate_checksum(const uint8_t *buf, size_t len)
{
    uint8_t payload_len = buf[2];
    uint8_t checksum = payload_len ^ buf[3];
    size_t i;

    for (i = 0; i < payload_len; i++) {
        checksum ^= buf[4 + i];
    }

    if (checksum != buf[4 + payload_len]) {
        return -5;
    }
    return 0;
}

static void copy_payload(const uint8_t *buf, uint8_t *out, size_t payload_len)
{
    size_t i;
    for (i = 0; i < payload_len; i++) {
        out[i] = buf[4 + i];
    }
}

int frame_parse(const uint8_t *buf, size_t len, uint8_t *type, uint8_t *out)
{
    int rc;

    rc = validate_input(buf, len, type, out);
    if (rc != 0) {
        return rc;
    }

    rc = validate_length(buf, len);
    if (rc != 0) {
        return rc;
    }

    rc = validate_type(buf);
    if (rc != 0) {
        return rc;
    }

    rc = validate_checksum(buf, len);
    if (rc != 0) {
        return rc;
    }

    *type = buf[3];
    copy_payload(buf, out, buf[2]);
    return buf[2];
}

