#define MODE_OFF    0
#define MODE_STANDBY 1
#define MODE_OPERATE 2
#define MODE_FAULT  3

#define EVENT_POWER_ON  0
#define EVENT_POWER_OFF 1
#define EVENT_START     2
#define EVENT_STOP      3
#define EVENT_ERROR     4
#define EVENT_CLEAR     5

static const uint8_t transition_table[4][6] = {
    /* Current mode \ Event */ 
    /* OFF     */ {MODE_STANDBY, MODE_OFF,   MODE_OFF,   MODE_OFF,   MODE_FAULT, MODE_OFF},
    /* STANDBY */ {MODE_OFF,   MODE_OFF,   MODE_OPERATE, MODE_OFF,   MODE_FAULT, MODE_STANDBY},
    /* OPERATE */ {MODE_OFF,   MODE_OFF,   MODE_OFF,   MODE_STANDBY, MODE_FAULT, MODE_OFF},
    /* FAULT   */ {MODE_OFF,   MODE_OFF,   MODE_OFF,   MODE_OFF,   MODE_FAULT, MODE_STANDBY}
};

void mode_init(mode_mgr_t *m)
{
    m->mode = MODE_OFF;
    m->transitions = 0;
}

int mode_handle(mode_mgr_t *m, uint8_t event)
{
    uint8_t next_mode = transition_table[m->mode][event];

    if (next_mode != m->mode) {
        m->mode = next_mode;
        m->transitions++;
        return 1;
    }

    return 0;
}

#include "task.h"

/* Bit field masks and shifts for byte 0 */
#define HK_MODE_MASK     0xC0U  /* bits 6-7 */
#define HK_HEATER_MASK   0x20U  /* bit 5 */
#define HK_FAULT_MASK    0x10U  /* bit 4 */
#define HK_CHANNEL_MASK  0x0FU  /* bits 0-3 */

/* Value clamping limits */
#define TEMP_MIN         -1000
#define TEMP_MAX         1500
#define BUS_MIN          0
#define BUS_MAX          40000
#define GAIN_MAX         63

static uint8_t clamp_and_pack_temp(int32_t temp)
{
    if (temp < TEMP_MIN) {
        temp = TEMP_MIN;
    } else if (temp > TEMP_MAX) {
        temp = TEMP_MAX;
    }
    return (uint8_t)((int16_t)temp & 0xFF);
}

static uint8_t clamp_and_pack_bus(int32_t bus)
{
    if (bus < BUS_MIN) {
        bus = BUS_MIN;
    } else if (bus > BUS_MAX) {
        bus = BUS_MAX;
    }
    return (uint8_t)((uint16_t)bus & 0xFF);
}

static uint8_t clamp_gain(uint8_t gain)
{
    if (gain > GAIN_MAX) {
        gain = GAIN_MAX;
    }
    return gain;
}

static void pack_byte0(const hk_t *hk, uint8_t *out)
{
    uint8_t b0 = 0;
    b0 |= (uint8_t)((hk->mode & 3) << 6);
    if (hk->heater_on) {
        b0 |= HK_HEATER_MASK;
    }
    if (hk->fault) {
        b0 |= HK_FAULT_MASK;
    }
    b0 |= (hk->channel & 15);
    out[0] = b0;
}

static void pack_temp(const hk_t *hk, uint8_t *out)
{
    int32_t temp = hk->temp_decic;
    uint16_t temp_u16 = (uint16_t)(int16_t)clamp_and_pack_temp(temp);
    out[1] = (uint8_t)(temp_u16 >> 8);
    out[2] = (uint8_t)temp_u16;
}

static void pack_bus(const hk_t *hk, uint8_t *out)
{
    int32_t bus = hk->bus_mv;
    uint16_t bus_u16 = (uint16_t)clamp_and_pack_bus(bus);
    out[3] = (uint8_t)(bus_u16 >> 8);
    out[4] = (uint8_t)bus_u16;
}

static void pack_gain(const hk_t *hk, uint8_t *out)
{
    out[5] = clamp_gain(hk->gain);
}

static void pack_counter(const hk_t *hk, uint8_t *out)
{
    uint16_t counter = hk->counter;
    out[6] = (uint8_t)(counter >> 8);
    out[7] = (uint8_t)counter;
}

void hk_pack(const hk_t *hk, uint8_t out[8])
{
    pack_byte0(hk, out);
    pack_temp(hk, out);
    pack_bus(hk, out);
    pack_gain(hk, out);
    pack_counter(hk, out);
}

