    CHECK_EQ_I(m.samples[3], 10);

    /* Test rolling window - first sample removed */
    CHECK_EQ_I(mavg_push(&m, 50), 30);  /* (20+30+40+50)/4 = 30 */
    CHECK_EQ_U(m.next, 1u);
    CHECK_EQ_U(m.count, 4u);
    CHECK_EQ_I(m.sum, 120);
    CHECK_EQ_I(m.samples[0], 40);
    CHECK_EQ_I(m.samples[1], 50);
    CHECK_EQ_I(m.samples[2], 30);
    CHECK_EQ_I(m.samples[3], 20);

    /* Test negative samples */
    mavg_reset(&m);
    CHECK_EQ_I(mavg_push(&m, -10), -10);
    CHECK_EQ_I(mavg_push(&m, -20), -15);  /* (-10 + -20)/2 = -15 */
    CHECK_EQ_I(mavg_push(&m, -30), -20);  /* (-10 + -20 + -30)/3 = -20 */

    /* Test mixed positive/negative samples */
    mavg_reset(&m);
    CHECK_EQ_I(mavg_push(&m, 10), 10);
    CHECK_EQ_I(mavg_push(&m, -20), -5);   /* (10 + -20)/2 = -5 */
    CHECK_EQ_I(mavg_push(&m, 30), 15);    /* (10 + -20 + 30)/3 = 15 */

    /* Test rounding toward zero */
    mavg_reset(&m);
    CHECK_EQ_I(mavg_push(&m, 7), 7);      /* 7/1 = 7 */
    CHECK_EQ_I(mavg_push(&m, 8), 7);      /* (7 + 8)/2 = 7.5 -> 7 */
    CHECK_EQ_I(mavg_push(&m, 9), 8);      /* (7 + 8 + 9)/3 = 8 */
    CHECK_EQ_I(mavg_push(&m, 10), 8);     /* (7 + 8 + 9 + 10)/4 = 8.5 -> 8 */

    /* Test with zero samples */
    mavg_reset(&m);
    CHECK_EQ_I(mavg_push(&m, 0), 0);
    CHECK_EQ_I(mavg_push(&m, 0), 0);
    CHECK_EQ_I(mavg_push(&m, 0), 0);

    /* Test edge case: maximum int32_t */
    mavg_reset(&m);
    CHECK_EQ_I(mavg_push(&m, 2147483647), 2147483647);
    CHECK_EQ_I(mavg_push(&m, 2147483647), 2147483647);

    /* Test edge case: minimum int32_t */
    mavg_reset(&m);
    CHECK_EQ_I(mavg_push(&m, -2147483648), -2147483648);
    CHECK_EQ_I(mavg_push(&m, -2147483648), -2147483648);

    return OGE_REPORT();
}

#include "task.h"
#include "oge_test.h"

int main(void)
{
    ring_buffer_t rb;

    // Test initialization
    rb_init(&rb);
    CHECK_EQ_U(rb.head, 0u);
    CHECK_EQ_U(rb.tail, 0u);
    CHECK_EQ_U(rb.count, 0u);

    // Test empty buffer behavior
    uint8_t out;
    CHECK_EQ_U(rb_count(&rb), 0u);
    CHECK_EQ_U(rb_pop(&rb, &out), false);
    CHECK_EQ_U(rb_count(&rb), 0u);

    // Test single push/pop
    CHECK_EQ_U(rb_push(&rb, 42u), true);
    CHECK_EQ_U(rb_count(&rb), 1u);
    CHECK_EQ_U(rb_pop(&rb, &out), true);
    CHECK_EQ_U(out, 42u);
    CHECK_EQ_U(rb_count(&rb), 0u);

    // Test multiple push/pop
    CHECK_EQ_U(rb_push(&rb, 1u), true);
    CHECK_EQ_U(rb_push(&rb, 2u), true);
    CHECK_EQ_U(rb_push(&rb, 3u), true);
    CHECK_EQ_U(rb_count(&rb), 3u);
    CHECK_EQ_U(rb_pop(&rb, &out), true);
    CHECK_EQ_U(out, 1u);
    CHECK_EQ_U(rb_pop(&rb, &out), true);
    CHECK_EQ_U(out, 2u);
    CHECK_EQ_U(rb_count(&rb), 1u);

    // Test full buffer behavior
    rb_init(&rb);
    for (size_t i = 0; i < RB_CAPACITY; i++) {
        CHECK_EQ_U(rb_push(&rb, (uint8_t)(i + 1)), true);
    }
    CHECK_EQ_U(rb_count(&rb), RB_CAPACITY);
    CHECK_EQ_U(rb_push(&rb, 99u), false);  // Should fail, buffer full
    CHECK_EQ_U(rb_count(&rb), RB_CAPACITY);

    // Test buffer wraparound
    rb_init(&rb);
    for (size_t i = 0; i < RB_CAPACITY; i++) {
        CHECK_EQ_U(rb_push(&rb, (uint8_t)(i + 1)), true);
    }
    CHECK_EQ_U(rb_pop(&rb, &out), true);
    CHECK_EQ_U(out, 1u);
    CHECK_EQ_U(rb_push(&rb, 99u), true);  // Should succeed, one slot freed
    CHECK_EQ_U(rb_count(&rb), RB_CAPACITY);

    // Test push_many with exact capacity
    rb_init(&rb);
    uint8_t src[RB_CAPACITY];
    for (size_t i = 0; i < RB_CAPACITY; i++) {
        src[i] = (uint8_t)(i + 100);
    }
    size_t stored = rb_push_many(&rb, src, RB_CAPACITY);
    CHECK_EQ_U(stored, RB_CAPACITY);
    CHECK_EQ_U(rb_count(&rb), RB_CAPACITY);
    for (size_t i = 0; i < RB_CAPACITY; i++) {
        CHECK_EQ_U(rb_pop(&rb, &out), true);
        CHECK_EQ_U(out, (uint8_t)(i + 100));
    }
    CHECK_EQ_U(rb_count(&rb), 0u);

    // Test push_many with more than capacity
    rb_init(&rb);
    stored = rb_push_many(&rb, src, RB_CAPACITY + 5);
    CHECK_EQ_U(stored, RB_CAPACITY);
    CHECK_EQ_U(rb_count(&rb), RB_CAPACITY);
    for (size_t i = 0; i < RB_CAPACITY; i++) {
        CHECK_EQ_U(rb_pop(&rb, &out), true);
        CHECK_EQ_U(out, (uint8_t)(i + 100));
    }
    CHECK_EQ_U(rb_count(&rb), 0u);

    // Test push_many with zero count
    rb_init(&rb);
    stored = rb_push_many(&rb, src, 0);
    CHECK_EQ_U(stored, 0u);
    CHECK_EQ_U(rb_count(&rb), 0u);

    // Test push_many with empty buffer
    rb_init(&rb);
    uint8_t empty[0];
    stored = rb_push_many(&rb, empty, 0);
    CHECK_EQ_U(stored, 0u);
    CHECK_EQ_U(rb_count(&rb), 0u);

    return OGE_REPORT();
}

