#include "task.h"
#include "oge_test.h"

int main(void)
{
    /* Test basic timeout functionality */
    CHECK(tick_elapsed(100, 50, 40));  /* 50ms elapsed, timeout 40ms -> elapsed */
    CHECK(!tick_elapsed(100, 50, 60)); /* 50ms elapsed, timeout 60ms -> not elapsed */

    /* Test exact timeout boundary */
    CHECK(tick_elapsed(100, 50, 50));  /* 50ms elapsed, timeout 50ms -> elapsed */

    /* Test wraparound cases */
    CHECK(tick_elapsed(0, 0xFFFFFFFF, 1)); /* Wraparound case */
    CHECK(!tick_elapsed(0, 0xFFFFFFFF, 2)); /* Wraparound case */

    /* Test remaining time calculations */
    CHECK_EQ_U(tick_remaining(100, 50, 60), 10); /* 10ms remaining */
    CHECK_EQ_U(tick_remaining(100, 50, 40), 0);  /* 0ms remaining */
    CHECK_EQ_U(tick_remaining(100, 50, 50), 0);  /* 0ms remaining exact */

    /* Test wraparound remaining time */
    CHECK_EQ_U(tick_remaining(0, 0xFFFFFFFF, 1), 0); /* Wraparound case */

    /* Test edge cases with zero timeout */
    CHECK(tick_elapsed(100, 50, 0));  /* Zero timeout should always be elapsed */
    CHECK_EQ_U(tick_remaining(100, 50, 0), 0); /* Zero timeout remaining should be 0 */

    /* Test large elapsed times */
    CHECK(tick_elapsed(0x80000000, 0x70000000, 0x10000000)); /* Large values */
    CHECK_EQ_U(tick_remaining(0x80000000, 0x70000000, 0x10000000), 0);

    /* Test that remaining time is always <= timeout */
    for (uint32_t start = 0; start < 1000; start += 100) {
        for (uint32_t now = start; now < start + 500; now += 50) {
            for (uint32_t timeout = 1; timeout < 100; timeout += 10) {
                uint32_t remaining = tick_remaining(now, start, timeout);
                CHECK(remaining <= timeout);
            }
        }
    }

    return OGE_REPORT();
}
